import hashlib, json, re, unicodedata
from pathlib import Path

source = Path('products/services/boamp-date-first-link-qa/raw/recent.json')
raw = source.read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == '63d92bb648d74bf27fc3546a30bef83281aa613c0372e51b0f721e4412dfe91c'
payload = json.loads(raw)
records = payload['results']

def strings(value, path=()):
    if isinstance(value, dict):
        for key, child in value.items():
            yield from strings(child, path + (key,))
    elif isinstance(value, list):
        for index, child in enumerate(value):
            yield from strings(child, path + (str(index),))
    elif isinstance(value, str):
        if value.lstrip().startswith(('{', '[')):
            try:
                decoded = json.loads(value)
            except ValueError:
                pass
            else:
                yield from strings(decoded, path + ('embedded_json',))
                return
        yield path, value

pattern = re.compile(r'liens? (?:brises?|morts?|cass[eé]s?|hypertextes?)|redirections?|migration (?:du|de) site|refonte (?:du|de) site|audit (?:du|de) site|contr[oô]le des liens', re.I)
rows = []
for index, record in enumerate(records):
    pointers = []
    for path, text in strings(record):
        if pattern.search(unicodedata.normalize('NFC', text)):
            pointers.append('.'.join(path))
    rows.append({'index': index, 'notice_id': record.get('idweb'), 'publication_date': record.get('dateparution'), 'response_deadline': record.get('datelimitereponse'), 'matching_field_paths': sorted(set(pointers))})

dates = [row['publication_date'] for row in rows if isinstance(row['publication_date'], str)]
result = {'source_sha256': digest, 'reported_total': payload.get('total_count'), 'returned_count': len(records), 'field_names': sorted({key for record in records for key in record}), 'date_coverage': {'min': min(dates, default=None), 'max': max(dates, default=None), 'all_rows_at_or_after_requested_date': bool(rows) and len(dates) == len(rows) and all(date[:10] >= '2026-11-16' for date in dates)}, 'rows': rows, 'limit': 'Field pointers only. Empty matches do not exclude a scope. Verify the original buyer notice, stage, deadline and acceptance wording before selecting a sample.'}
output = source.parent.parent / 'date-and-scope-pointers.json'
output.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
assert json.loads(output.read_text(encoding='utf-8')) == result
print(json.dumps({'artifact': str(output), 'returned_count': len(records), 'date_coverage': result['date_coverage'], 'rows_with_pointers': sum(bool(row['matching_field_paths']) for row in rows)}))
